<?php $cart=$_SESSION['cart']??[]; $subtotal=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$cart)); $flash=$_SESSION['flash']??null; unset($_SESSION['flash']); ?>
<section class="checkout-head"><p class="site-kicker">FINALISER VOTRE COMMANDE</p><h1>Votre panier <span><?= count($cart) ?> article<?= count($cart)>1?'s':'' ?></span></h1></section>
<?php if($flash): ?><div class="site-flash"><?= htmlspecialchars($flash) ?></div><?php endif ?>
<?php if(!$cart): ?><section class="cart-empty"><strong>Votre panier est vide</strong><p>Explorez nos formations ou nos équipements professionnels.</p><div><a class="site-btn green" href="/formations">Voir les formations</a><a class="site-btn outline" href="/boutique">Voir la boutique</a></div></section><?php else: ?>
<section class="checkout-layout"><div class="checkout-main"><div class="checkout-box"><div class="box-heading"><h2>Votre sélection</h2><form method="post" action="/panier/vider"><button class="text-danger">Vider le panier</button></form></div><?php foreach($cart as $key=>$item): ?><article class="cart-item"><div class="cart-thumb <?= $key==='training'?'navy':'coral' ?>">IF</div><div><span><?= $key==='training'?'FORMATION':'PRODUIT' ?></span><h3><?= htmlspecialchars($item['name']) ?></h3><small>Quantité : <?= $item['quantity'] ?></small><form method="post" action="/panier/supprimer"><input type="hidden" name="key" value="<?= htmlspecialchars($key) ?>"><button>Supprimer</button></form></div><strong><?= number_format($item['price']*$item['quantity'],0,',',' ') ?> FCFA</strong></article><?php endforeach ?></div></div><aside class="summary-card"><h2>Récapitulatif</h2><p><span>Sous-total</span><b><?= number_format($subtotal,0,',',' ') ?> FCFA</b></p><p><span>Livraison</span><b class="free">Calculée à l’étape suivante</b></p><hr><p class="total"><span>Total provisoire</span><strong><?= number_format($subtotal,0,',',' ') ?> FCFA</strong></p><a class="site-btn gold wide" href="/commande">Continuer la commande →</a><small class="safe">🔒 Transaction sécurisée</small></aside></section><?php endif ?>
